source_context:
 1: ---
 2: - hosts: localhost
 3:   gather_facts: no
 4:   tasks:
 5:     - hashivault_auth_list:
 6:       register: auth_list
 7:     - assert: { that: "'token/' in auth_list.backends" }
 8:     - assert: { that: "'userpass/' not in auth_list.backends" }
 9:     - name: Delete any lingering userpass
10:       hashivault_auth_method:
11:         method_type: "userpass"
12:         state: disable
13:       failed_when: False
14:     - name: Enable userpass first time for this test
15:       hashivault_auth_method:
16:         method_type: "userpass"
17:         description: "my userpass"
18:       register: 'vault_auth'
19:     - assert: { that: "vault_auth is changed" }
20:     - assert: { that: "vault_auth.created == True" }
21:     - assert: { that: "vault_auth.failed == False" }
22:     - assert: { that: "vault_auth.rc == 0" }
23:     - hashivault_auth_list:
24:       check_mode: true
25:       register: auth_list
26:     - assert: { that: "'userpass/' in auth_list.backends" }
27:     - name: Enable userpass when it is already enabled
28:       hashivault_auth_method:
29:         method_type: "userpass"
30:         description: "my userpass"
31:       register: 'vault_auth'
32:     - assert: { that: "vault_auth is not changed" }
33:     - assert: { that: "vault_auth.created == False" }
34:     - assert: { that: "vault_auth.failed == False" }
35:     - assert: { that: "vault_auth.rc == 0" }
36:     - name: Enable userpass auth for the third time with change
37:       hashivault_auth_method:
38:         method_type: "userpass"
39:         description: "our userpass"
40:       register: 'vault_auth'
41:     - assert: { that: "vault_auth is changed" }
42:     - assert: { that: "vault_auth.created == False" }
43:     - assert: { that: "vault_auth.rc == 0" }
44:     - name: Enable userpass at a different mount point
45:       hashivault_auth_method:
46:         method_type: "userpass"
47:         mount_point: "another-userpass"
48:       register: 'vault_auth_mount_point'
49:     - assert: { that: "vault_auth_mount_point is changed" }
50:     - assert: { that: "vault_auth_mount_point.rc == 0" }

 1: - name: Cluster {{ cluster_id }} - Create directories
 2:   file:
 3:     path: "{{ item }}"
 4:     state: directory
 5:     mode: 0755 # For some reason, item.mode converts 0755 into 493 ... weird
 6:   loop:
 7:     - clusters/{{ cluster_id }}
 8: 
 9: - name: Cluster {{ cluster_id }} - Create openshift-install configuration
10:   template:
11:     src: "{{ item.src }}"
12:     dest: "{{ item.dest }}"
13:   vars:
14:     ssh_pub_key: "{{ ssh_pub_key_task.stdout }}"
15:     pull_secret: "{{ lookup('file', './files/pull_secret.txt', errors='ignore') }}"
16:   with_items:
17:     - {
18:         src: templates/install-config.yaml.j2,
19:         dest: "clusters/{{ cluster_id }}/install-config.yaml",
20:       }
21:     - {
22:         src: templates/agent-config.yaml.j2,
23:         dest: "clusters/{{ cluster_id }}/agent-config.yaml",
24:       }
25:   register: okd_installer_config_files
26: 
27: # Let's create the proper OKD installation files (ignition, manifests, ...)
28: - name: Cluster {{ cluster_id }} - Run openshift-installer
29:   when: okd_installer_config_files.changed
30:   shell: |
31:     cd clusters/{{ cluster_id }}
32:     rm -rf install-dir
33:     mkdir install-dir
34:     cp install-config.yaml agent-config.yaml install-dir/
35:     {% if ipxe.enabled %}
36:       {% set cmd = "pxe-files" %}
37:     {% else %}
38:       {% set cmd = "image" %}
39:     {% endif %}
40:     openshift-install agent create {{ cmd }} --dir=install-dir
41:   environment:
42:     PATH: "/usr/local/bin:/usr/bin:/bin"
43:   register: installer_task
44: 
45: # Make these files available on the Web server
46: - name: Cluster {{ cluster_id }} - Copy boot-artifacts to www directory
47:   when: installer_task.changed
48:   become: true
49:   shell: |
50:     rm -rf /var/www/html/{{ cluster_id }}
51:     mkdir /var/www/html/{{ cluster_id }}
52:     {% if ipxe.enabled %}
53:     cp -R clusters/{{ cluster_id }}/install-dir/boot-artifacts/* /var/www/html/{{ cluster_id }}
54:     {% else %}
55:     cp clusters/{{ cluster_id }}/install-dir/agent.x86_64.iso /var/www/html/{{ cluster_id }}/
56:     {% endif %}
57:     chmod -R 755 /var/www/html/{{ cluster_id }}

