 7: ---
 8: 
 9: - name: (Deprecation) Catch and report renamed Honoroit settings
10:   ansible.builtin.fail:
11:     msg: >-
12:       Your configuration contains a variable, which now has a different name.
13:       Please rename the variable (`{{ item.old }}` -> `{{ item.new }}`) on your configuration file (vars.yml).
14:   when: "lookup('ansible.builtin.varnames', ('^' + item.old + '$'), wantlist=True) | length > 0"
15:   with_items:
16:     - {'old': 'matrix_bot_honoroit_container_image_name_prefix', 'new': 'matrix_bot_honoroit_container_image_registry_prefix'}
17:     - {'old': 'matrix_bot_honoroit_docker_image', 'new': 'matrix_bot_honoroit_container_image'}
18:     - {'old': 'matrix_bot_honoroit_docker_image_force_pull', 'new': 'matrix_bot_honoroit_container_image_force_pull'}
19:     - {'old': 'matrix_bot_honoroit_container_image_force_pull', 'new': '<removed> (the new community.docker.docker_image_pull module handles this natively)'}
20:     - {'old': 'matrix_bot_honoroit_docker_image_registry_prefix', 'new': 'matrix_bot_honoroit_container_image_registry_prefix'}
21:     - {'old': 'matrix_bot_honoroit_docker_image_registry_prefix_upstream', 'new': 'matrix_bot_honoroit_container_image_registry_prefix_upstream'}
22:     - {'old': 'matrix_bot_honoroit_docker_image_registry_prefix_upstream_default', 'new': 'matrix_bot_honoroit_container_image_registry_prefix_upstream_default'}
23:     - {'old': 'matrix_bot_honoroit_docker_repo', 'new': 'matrix_bot_honoroit_container_repo'}
24:     - {'old': 'matrix_bot_honoroit_docker_repo_version', 'new': 'matrix_bot_honoroit_container_repo_version'}
25:     - {'old': 'matrix_bot_honoroit_docker_src_files_path', 'new': 'matrix_bot_honoroit_container_src_files_path'}
26: 
27: - name: Fail if required Honoroit settings not defined
28:   ansible.builtin.fail:
29:     msg: >-
30:       You need to define a required configuration setting (`{{ item.name }}`).
31:   when: "item.when | bool and lookup('vars', item.name, default='') | string | length == 0"
32:   with_items:
33:     - {'name': 'matrix_bot_honoroit_homeserver', when: true}
34:     - {'name': 'matrix_bot_honoroit_password', when: true}
35:     - {'name': 'matrix_bot_honoroit_roomid', when: true}
36:     - {'name': 'matrix_bot_honoroit_database_hostname', when: "{{ matrix_bot_honoroit_database_engine == 'postgres' }}"}
